#!/usr/bin/env python3
import argparse, pathlib, subprocess, tempfile, textwrap, shutil, sys

TCL = """
    # auto-generated helper for one structure
    scripting::open --xsf "{xsf}"
    scripting::display forces on           ;# show force vectors
    scripting::display forces scale {scale}
    printToFile "{png}"
    exit
"""

def main():
    p = argparse.ArgumentParser(
        description="Make force-vector snapshots for every XSF in a folder")
    p.add_argument("-d", "--dir", default=".", type=pathlib.Path,
                   help="folder with .xsf files (default: current)")
    p.add_argument("--scale", default=0.4, type=float,
                   help="arrow-length scaling factor (default: 0.4)")
    p.add_argument("--keep", action="store_true",
                   help="keep the temporary .tcl files")
    args = p.parse_args()

    xsfs = sorted(args.dir.glob("*.xsf")) + sorted(args.dir.glob("*.axsf"))
    if not xsfs:
        sys.exit("✖  no .xsf / .axsf files found")

    use_xvfb = shutil.which("xvfb-run") is not None
    for f in xsfs:
        png = f.with_suffix(".png").absolute()
        with tempfile.NamedTemporaryFile("w", delete=not args.keep,
                                         suffix=".tcl") as t:
            t.write(textwrap.dedent(TCL).format(
                    xsf=f.absolute(), png=png, scale=args.scale))
            t.flush()
            cmd = (["xvfb-run", "-a"] if use_xvfb else []) + \
                  ["xcrysden", "--script", t.name]
            print(f"▶ {f.name}  →  {png.name}")
            subprocess.run(cmd, check=True)
    print("✓  all snapshots finished")

if __name__ == "__main__":
    main()
#==================================================================================
